input.content:
*{box-sizing:border-box}
:root{font-family:'Nunito',ui-rounded,system-ui,sans-serif;color:#07546d;font-synthesis:none;font-optical-sizing:auto}
body{margin:0;min-height:100vh;display:grid;place-items:center;overflow:hidden;background:radial-gradient(ellipse at 18% 0%,#fff 0%,#e7fcff 29%,transparent 55%),linear-gradient(145deg,#dcfbff,#aeeef5 48%,#ddfff5);padding:18px}
button{font-family:inherit}
.shell{width:min(1120px,100%);height:min(820px,calc(100dvh - 36px));min-height:500px;display:flex;flex-direction:column;gap:14px}
.topbar{height:48px;display:flex;align-items:center;justify-content:space-between;padding:0 6px;flex-shrink:0}
.brand{display:flex;align-items:center;gap:10px;color:#0783a4;font-size:15px;font-weight:900;letter-spacing:2px;text-decoration:none}
.brand-light{font-weight:600;color:#48a9b5}
.brand-mark{display:grid;place-items:center;width:34px;height:34px;border-radius:12px;color:#fff;font-size:19px;background:linear-gradient(145deg,#52d9d4,#42b1ed);box-shadow:inset 0 2px 3px #ffffffb3,0 5px 12px #3abbd444}
.top-note{font-size:12px;font-weight:700;color:#5a9aa8;letter-spacing:.25px}
.live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#57cfa6;box-shadow:0 0 0 4px #75e2ba33;margin-right:8px}
.glass-button{border:1px solid #ffffffbd;background:linear-gradient(145deg,#ffffffc7,#e8fbff9c);color:#1385a1;box-shadow:0 4px 12px #3d9bb11a,inset 0 1px 2px #fff;border-radius:14px;font-weight:800;cursor:pointer;transition:transform .2s,box-shadow .2s;backdrop-filter:blur(12px)}
.glass-button:hover{transform:translateY(-2px);box-shadow:0 7px 16px #3d9bb12b,inset 0 1px 2px #fff}
.sound-button{padding:9px 14px;font-size:13px}
.sound-button span{font-size:11px;margin-left:4px;color:#5a9aa8}
.game-wrap{position:relative;flex:1;min-height:0;overflow:hidden;border-radius:28px;border:1px solid #ffffffd9;background:#3bbdd2;box-shadow:0 24px 60px #1888a226,0 3px 9px #0e779122,inset 0 1px 1px #fff;isolation:isolate}
.game-wrap:before{content:"";position:absolute;inset:0;z-index:5;pointer-events:none;border:1px solid #ffffff4a;border-radius:inherit}
#world{position:absolute;inset:0;z-index:0;touch-action:none}
#world canvas{display:block;width:100%;height:100%;touch-action:none;outline:0}
.vignette{position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(180deg,#d9ffff1c 0%,transparent 23%,transparent 72%,#116e7130 100%),radial-gradient(ellipse at center,transparent 58%,#175f6740 100%)}
.hud{position:absolute;z-index:3;inset:18px 20px auto;display:flex;align-items:flex-start;gap:10px;pointer-events:none}
.hud-card,.glass-panel{border:1px solid #ffffffa6;background:linear-gradient(145deg,#ffffffc9,#edffff91);box-shadow:0 8px 24px #186e7824,inset 0 1px 2px #ffffff;backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px)}
.hud-card{border-radius:16px;padding:10px 14px;min-width:132px;color:#0b7181}
.hud-label{display:block;font-size:9px;font-weight:900;letter-spacing:1.55px;color:#4f9da3}
.score-line,.air-line{display:flex;align-items:center;gap:7px;margin-top:1px;line-height:1.3}
.score-line strong,.air-line strong{font-size:23px;font-weight:900;color:#087c91}
.score-target{font-size:13px;font-weight:800;color:#72aeb0}
.pearl-icon{font-size:21px;color:#21b9ad;text-shadow:0 1px 8px #64eedc}
.air-icon{font-size:20px;color:#2589b2}
.progress-track{height:4px;margin-top:5px;border-radius:9px;background:#14889c24;overflow:hidden}
.progress-track i{display:block;width:0;height:100%;border-radius:inherit;background:linear-gradient(90deg,#52dcc0,#40afd8);box-shadow:0 0 8px #45d9cd;transition:width .35s ease}
.explore-card{min-width:131px}
.map-card{position:absolute;right:47px;top:0;width:136px;height:155px;border-radius:18px;padding:5px;display:flex;flex-direction:column;align-items:center;gap:1px}
#map{display:block;width:116px;height:116px;border-radius:50%;filter:drop-shadow(0 2px 4px #117d8533)}
.map-label{font-size:8px;font-weight:900;letter-spacing:1.2px;color:#4e999d}
.pause-button{pointer-events:auto;margin-left:auto;width:40px;height:40px;border-radius:13px;font-size:15px}
.location-chip{position:absolute;z-index:3;left:50%;bottom:22px;transform:translateX(-50%);padding:8px 15px;border-radius:99px;background:#ffffffa8;border:1px solid #ffffffc9;color:#267b86;box-shadow:0 6px 18px #176c7730;backdrop-filter:blur(12px);font-size:11px;font-weight:700;letter-spacing:.2px;white-space:nowrap;pointer-events:none}
.location-chip span{margin-right:5px;color:#31b69e;font-size:14px}
.center-overlay{position:absolute;inset:0;z-index:6;display:grid;place-items:center;padding:18px;background:linear-gradient(90deg,#e4ffff18,#e1ffff08);transition:opacity .35s,visibility .35s}
.center-overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}
.overlay-card{position:relative;width:min(440px,calc(100% - 24px));padding:20px 34px 18px;text-align:center;border-radius:28px;color:#145e72;box-shadow:0 18px 55px #0d70813d,inset 0 1px 2px #fff;background:linear-gradient(145deg,#f7ffffe8,#d9fbf5d9);animation:floatIn .55s cubic-bezier(.2,.8,.2,1) both}
@keyframes floatIn{from{transform:translateY(12px) scale(.97);opacity:0}to{transform:translateY(0) scale(1);opacity:1}}
.eyebrow{font-size:9px;font-weight:900;letter-spacing:1.65px;color:#58a3a5}
.eyebrow span{color:#f3bd62;font-size:14px;vertical-align:-1px;margin-right:4px}
.mascot{position:relative;width:65px;height:57px;margin:12px auto 4px;border-radius:55% 48% 48% 52%;transform:rotate(-8deg);background:linear-gradient(145deg,#c8fff1 0%,#5ed9d2 48%,#29a8c1 100%);box-shadow:inset 0 4px 8px #ffffffc9,inset 0 -7px 10px #087e9d47,0 9px 18px #29aabd44}
.mascot:before{content:"";position:absolute;width:18px;height:25px;right:-10px;top:17px;border-radius:3px 90% 8px 90%;transform:rotate(22deg);background:linear-gradient(135deg,#62e3cf,#209dbb);box-shadow:inset 2px 2px 3px #ffffff88}
.mascot-shine{position:absolute;left:12px;top:8px;width:24px;height:8px;border-radius:100%;transform:rotate(-20deg);background:#ffffffb8;filter:blur(1px)}
.mascot-eye{position:absolute;right:14px;top:22px;width:6px;height:7px;border-radius:50%;background:#07506b;box-shadow:1px -1px 0 2px #f4ffff}
.mascot-fin{position:absolute;left:7px;bottom:-6px;color:#c1fff0;font-size:25px;transform:rotate(90deg)}
h1{font-size:35px;line-height:1.1;margin:7px 0 8px;font-weight:900;letter-spacing:-1px;color:#087390}
h1 em{font-style:normal;color:#37b7ab}
.overlay-card p{font-size:13px;line-height:1.6;margin:0 0 16px;color:#568893;font-weight:700}
.how-to{display:flex;align-items:center;justify-content:center;gap:5px;margin:0 auto 15px;color:#57919b;font-size:10px;font-weight:800}
.keycap{display:inline-grid;place-items:center;min-width:21px;height:21px;border-radius:6px;background:#ffffffbf;border:1px solid #bde8e6;box-shadow:0 2px 0 #9fd4d4;color:#24869a;font-size:10px;font-weight:900}
.keycap.wide{min-width:43px;letter-spacing:.4px}
.or{margin-left:5px;margin-right:7px;color:#81aeb0}
.instructions-text{margin-left:2px}
.primary-button{border:0;border-radius:14px;padding:12px 21px;color:#fff;background:linear-gradient(135deg,#56d4bd,#2da9c9);box-shadow:0 7px 16px #24a7b649,inset 0 1px 2px #ffffff9e;font-size:13px;font-weight:900;cursor:pointer;transition:transform .2s,filter .2s}
.primary-button:hover{transform:translateY(-2px);filter:saturate(1.12)}
.primary-button span{margin-left:10px;font-size:16px}
.best-note{margin-top:13px;color:#79aeb0;font-size:8px;letter-spacing:1.65px;font-weight:900}
.toast{position:absolute;z-index:4;top:88px;left:50%;transform:translate(-50%,-8px);padding:10px 17px;border-radius:99px;background:#ffffffd9;border:1px solid #fff;color:#128595;font-size:12px;font-weight:900;box-shadow:0 7px 20px #1a748633;opacity:0;transition:opacity .24s,transform .24s;pointer-events:none;white-space:nowrap;backdrop-filter:blur(10px)}
.toast.show{opacity:1;transform:translate(-50%,0)}
.mobile-controls{display:none}
.footer{height:25px;display:flex;align-items:center;justify-content:space-between;padding:0 8px;flex-shrink:0;color:#55a0a9;font-size:11px;font-weight:700}
.footer b{color:#188ba0}
.footer-right span{font-size:15px;vertical-align:-1px;margin-left:4px;color:#3fbfae}
@media(max-width:680px){
 body{padding:8px;overflow:hidden}
 .shell{height:calc(100dvh - 16px);min-height:420px;gap:7px}
 .topbar{height:39px;padding:0 3px}
 .brand{font-size:12px;gap:7px}.brand-mark{width:29px;height:29px;border-radius:10px;font-size:16px}
 .top-note{font-size:10px}.sound-button{padding:7px 9px;font-size:11px}.sound-button span{font-size:9px}
 .game-wrap{border-radius:21px}
 .hud{inset:10px 10px auto;gap:6px}
 .hud-card{min-width:98px;padding:7px 9px;border-radius:13px}
 .hud-label{font-size:7px;letter-spacing:1px}.score-line,.air-line{gap:4px}.score-line strong,.air-line strong{font-size:18px}.score-target{font-size:10px}.pearl-icon,.air-icon{font-size:16px}.progress-track{height:3px;margin-top:3px}
 .explore-card{min-width:98px}
 .map-card{top:73px;right:0;width:100px;height:113px;padding:4px;border-radius:14px;gap:0}
 #map{width:86px;height:86px}.map-label{font-size:6px;letter-spacing:.8px}
 .pause-button{width:34px;height:34px;border-radius:11px}
 .location-chip{bottom:12px;font-size:9px;padding:6px 11px}
